/* ==========================================================================
   art.js — everything the site draws with code
   --------------------------------------------------------------------------
   Kept in its own file so the visual language can be tuned in one place:
     · ICONS      — 24px hairline icon set (replaces the old emoji)
     · PALETTE    — planet colours: bright core → deep edge
     · planetSVG  — lit spheres (body + feature layer + terminator shade + rim)
     · guideSVG   — 地小球 / Earthie, the guide character (normal + four emotions)
     · termIconSVG— pre-training term icons
     · orbitMapSVG— the Solar System map (narrative mode: motion + trajectory)
   Theory notes are inline, and mirrored in 设计说明-Design-Notes.md.
   This file only *defines* functions; the data (PLANETS) lives in script.js and
   is read at call time.
   ========================================================================== */

/* ---------- 1. Icon set ----------
   Icons inherit currentColor and use one hairline weight (1.7) so the whole UI
   reads as one family. Emoji were removed: they render differently on every
   device and read as decoration.                              [L3-Coherence] */
const ICONS = {
  home: '<path d="M3.2 10.6 12 3.4l8.8 7.2"/><path d="M5.6 9.6V20.6h12.8V9.6"/>',
  brain: '<path d="M12 5.2v13.6"/><path d="M12 7.4a2.9 2.9 0 0 0-4.8-1A2.5 2.5 0 0 0 5.3 9a2.7 2.7 0 0 0 .9 4.4 2.7 2.7 0 0 0 2.9 3.3 2.9 2.9 0 0 0 2.9-1.9"/><path d="M12 7.4a2.9 2.9 0 0 1 4.8-1A2.5 2.5 0 0 1 18.7 9a2.7 2.7 0 0 1-.9 4.4 2.7 2.7 0 0 1-2.9 3.3A2.9 2.9 0 0 1 12 14.8"/>',
  planet: '<circle cx="12" cy="12" r="5.1"/><ellipse cx="12" cy="12" rx="9.4" ry="3.5" transform="rotate(-18 12 12)"/>',
  gamepad: '<rect x="2.6" y="7.6" width="18.8" height="10" rx="3.4"/><path d="M7.6 10.6v3M6.1 12.1h3"/><circle cx="16.2" cy="11.4" r="1.15"/><circle cx="18" cy="13.4" r="1.15"/>',
  star: '<path d="m12 3.8 2.55 5.3 5.75.8-4.2 4 1.05 5.75L12 16.9l-5.15 2.75L7.9 13.9l-4.2-4 5.75-.8z"/>',
  globe: '<circle cx="12" cy="12" r="8.4"/><path d="M3.7 12h16.6"/><path d="M12 3.6c2.5 2.7 2.5 14.1 0 16.8-2.5-2.7-2.5-14.1 0-16.8Z"/>',
  speaker: '<path d="M4.6 9.4h2.9l4-3.5v12.2l-4-3.5H4.6z"/><path d="M15.4 9.3a4 4 0 0 1 0 5.4"/><path d="M17.9 6.9a7.3 7.3 0 0 1 0 10.2"/>',
  captions: '<rect x="3" y="5.6" width="18" height="12.8" rx="3"/><path d="M9.9 10.4a2.1 2.1 0 1 0 0 3.2M16.4 10.4a2.1 2.1 0 1 0 0 3.2"/>',
  pause: '<path d="M9.6 6.2v11.6M14.4 6.2v11.6"/>',
  tag: '<path d="M11.5 3.7H6.4a2 2 0 0 0-2 2v5.1a2 2 0 0 0 .6 1.4l6.3 6.3a2 2 0 0 0 2.8 0l5.1-5.1a2 2 0 0 0 0-2.8l-6.3-6.3a2 2 0 0 0-1.4-.6Z"/><circle cx="8.4" cy="8.4" r="1.05"/>',
  close: '<path d="m6.8 6.8 10.4 10.4M17.2 6.8 6.8 17.2"/>',
  chevronRight: '<path d="m9.6 5.6 6.4 6.4-6.4 6.4"/>',
  chevronLeft: '<path d="m14.4 5.6-6.4 6.4 6.4 6.4"/>',
  play: '<path d="M8.4 5.6 18 12l-9.6 6.4z"/>',
  drag: '<path d="M12 4.4v15.2M4.4 12h15.2"/><path d="m9.2 7.2 2.8-2.8 2.8 2.8M9.2 16.8l2.8 2.8 2.8-2.8M7.2 9.2 4.4 12l2.8 2.8M16.8 9.2 19.6 12l-2.8 2.8"/>',
  think: '<path d="M20.2 12.4c0 3.5-3.7 6.4-8.2 6.4-1 0-2-.15-2.9-.43L4.6 20l1.2-3.3A6.5 6.5 0 0 1 3.8 12.4C3.8 8.9 7.5 6 12 6s8.2 2.9 8.2 6.4Z"/><path d="M9.2 12.4h.02M12 12.4h.02M14.8 12.4h.02"/>',
  check: '<path d="m20 6.8-10.4 10.4L4.6 12.2"/>',
  bulb: '<path d="M9.4 17.2h5.2M10.4 20.2h3.2"/><path d="M12 3.6a5.4 5.4 0 0 0-3.2 9.8c.5.36.8.9.8 1.5h4.8c0-.6.3-1.14.8-1.5A5.4 5.4 0 0 0 12 3.6Z"/>',
  refresh: '<path d="M20 12a8 8 0 1 1-2.35-5.65"/><path d="M20.2 4.6v5.2h-5.2"/>',
  save: '<path d="M4.6 5.6a1 1 0 0 1 1-1h9.1L19.4 9v9.4a1 1 0 0 1-1 1H5.6a1 1 0 0 1-1-1z"/><path d="M8.2 4.6v5h5.6M8.2 19.4V13h7.6v6.4"/>',
  search: '<circle cx="10.7" cy="10.7" r="6.2"/><path d="m15.3 15.3 4.2 4.2"/>',
  arrowRight: '<path d="M4.6 12h14"/><path d="m13.2 6.6 5.4 5.4-5.4 5.4"/>',
  arrowUp: '<path d="M12 19.4V4.6"/><path d="m6.6 10 5.4-5.4L17.4 10"/>',
  sparkle: '<path d="M12 4 13.6 9l5 1.6-5 1.6L12 17.2l-1.6-5-5-1.6 5-1.6z"/>'
};

function iconSVG(name) {
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" ' +
    'stroke-linecap="round" stroke-linejoin="round">' + (ICONS[name] || ICONS.star) + '</svg>';
}

/* Fill every empty [data-icon] slot. Runs on load and on DOM changes, so
   script-generated markup (term cards, practice buttons) is covered too. */
let iconsRendering = false;
function renderIcons() {
  if (iconsRendering) return;
  iconsRendering = true;
  document.querySelectorAll('[data-icon]').forEach(function (el) {
    if (!el.dataset.iconDone) {
      el.innerHTML = iconSVG(el.dataset.icon);
      el.dataset.iconDone = '1';
    }
  });
  iconsRendering = false;
}

/* ---------- 2. Planet palette ----------
   Three stops per body: [highlight, base, shadow]. Desaturated mid-tones with a
   bright specular core read as "premium" instead of flat primary colours. */
const PALETTE = {
  sun:     ['#fff3cf', '#ffc24b', '#e8890c'],
  mercury: ['#d7dbe6', '#a8afbd', '#5d6472'],
  venus:   ['#fff0ce', '#efc178', '#b8853a'],
  earth:   ['#bfe9ff', '#58b6ee', '#1b5fa8'],
  mars:    ['#ffc9ae', '#e0734c', '#9e3d1e'],
  jupiter: ['#ffe7c6', '#dca972', '#a06a34'],
  saturn:  ['#fff6de', '#e7d4a2', '#bfa067'],
  uranus:  ['#e3fbfd', '#93dbe2', '#4e9aa6'],
  neptune: ['#cbd9ff', '#7089e6', '#2f4ba6']
};

/* ---------- 3. Faces ----------
   Eyes + smile = Demand gaze on the "meet your neighbours" cards and the guide:
   the character looks straight at the learner.            [L2-Interactive]
   Faces are only used on the four inner planets and the guide — the factual
   figures (Sun, giants) stay non-anthropomorphic so the science stays accurate. */
function faceMarkup(cx, cy, s) {
  const ex = 8.4 * s, ey = 5.6 * s, er = 3.1 * s;
  return '<g class="face">' +
    '<ellipse cx="' + (cx - ex) + '" cy="' + cy + '" rx="' + er + '" ry="' + (er * 1.12) + '" fill="#0b1024"/>' +
    '<ellipse cx="' + (cx + ex) + '" cy="' + cy + '" rx="' + er + '" ry="' + (er * 1.12) + '" fill="#0b1024"/>' +
    '<circle cx="' + (cx - ex + 1.1 * s) + '" cy="' + (cy - 1.2 * s) + '" r="' + (er * 0.4) + '" fill="#fff"/>' +
    '<circle cx="' + (cx + ex + 1.1 * s) + '" cy="' + (cy - 1.2 * s) + '" r="' + (er * 0.4) + '" fill="#fff"/>' +
    '<path d="M ' + (cx - 6.4 * s) + ' ' + (cy + ey + 3.4 * s) + ' q ' + (6.4 * s) + ' ' + (5.4 * s) + ' ' + (12.8 * s) + ' 0' +
      '" stroke="#0b1024" stroke-width="' + (1.7 * s) + '" fill="none" stroke-linecap="round"/>' +
    '<ellipse class="blink" cx="' + (cx - ex) + '" cy="' + cy + '" rx="' + er + '" ry="' + (er * 1.12) + '" fill="#0b1024"/>' +
    '<ellipse class="blink" cx="' + (cx + ex) + '" cy="' + cy + '" rx="' + er + '" ry="' + (er * 1.12) + '" fill="#0b1024"/>' +
  '</g>';
}

/* ---------- 4. Planet illustrations ----------
   Layer order = body → surface features → terminator shade → specular sheen →
   rim light. The shade is what makes a flat circle look like a lit sphere. */
function planetSVG(key, size, opts) {
  const o = opts || {};
  const c = PALETTE[key] || PALETTE.mercury;
  const S = 200, cx = 100, cy = 100;
  const uid = 'g-' + key + '-' + Math.random().toString(36).slice(2, 7);
  let inner = '';

  if (key === 'sun') {
    /* Sun: layered glow + corona + lit core.       [L2-Salience] brightest body */
    inner =
      '<g class="sun-core">' +
        '<circle cx="100" cy="100" r="86" fill="url(#' + uid + '-glow)" opacity=".55"/>' +
        '<circle cx="100" cy="100" r="62" fill="' + c[1] + '" opacity=".22"/>' +
        '<circle cx="100" cy="100" r="48" fill="url(#' + uid + '-body)"/>' +
        '<ellipse cx="84" cy="82" rx="20" ry="14" fill="url(#' + uid + '-spec)" opacity=".75"/>' +
        '<circle cx="118" cy="122" r="7" fill="#e8890c" opacity=".28"/>' +
        '<circle cx="86" cy="126" r="4.6" fill="#e8890c" opacity=".22"/>' +
        '<circle cx="100" cy="100" r="48" fill="none" stroke="#fff6d8" stroke-width="1" opacity=".5"/>' +
      '</g>';
  } else {
    const bodyR = key === 'jupiter' || key === 'saturn' ? 60 : 60;
    let features = '';

    if (key === 'mercury') {
      features =
        '<circle cx="78" cy="84" r="9.5" fill="#7f8695" opacity=".5"/>' +
        '<circle cx="119" cy="113" r="6.5" fill="#7f8695" opacity=".42"/>' +
        '<circle cx="103" cy="70" r="4" fill="#7f8695" opacity=".4"/>' +
        '<circle cx="66" cy="118" r="3.4" fill="#7f8695" opacity=".3"/>' +
        '<path d="M50 118 q30 14 62 6 t44 2" stroke="#8f95a3" stroke-width="1.4" fill="none" opacity=".35"/>';
    }
    if (key === 'venus') {
      features =
        '<path d="M44 86 q30 -13 58 -4 t54 -6" stroke="#ffe6b4" stroke-width="6" fill="none" opacity=".45" stroke-linecap="round"/>' +
        '<path d="M42 112 q34 12 60 2 t56 4" stroke="#d99f5c" stroke-width="5" fill="none" opacity=".35" stroke-linecap="round"/>' +
        '<path d="M52 68 q26 -8 50 -2" stroke="#ffe6b4" stroke-width="3.4" fill="none" opacity=".3" stroke-linecap="round"/>';
    }
    if (key === 'earth') {
      /* Continents + cloud veil + a thin atmosphere ring. The blue-green read is
         the visual anchor for "water, air, life".                  [L2-Salience] */
      features =
        '<path d="M56 74 q16 -12 30 -2 q9 8 0 15 q-14 10 -30 -2 q-6 -6 0 -11z" fill="#63c98a" opacity=".92"/>' +
        '<path d="M104 96 q22 -10 34 6 q10 14 -6 23 q-18 12 -32 -4 q-8 -13 4 -25z" fill="#4fae7a" opacity=".9"/>' +
        '<path d="M70 132 q18 -8 28 4 q6 8 -8 10 q-18 2 -20 -14z" fill="#63c98a" opacity=".8"/>' +
        '<path d="M44 92 q22 8 40 2" stroke="#ffffff" stroke-width="4" fill="none" opacity=".5" stroke-linecap="round"/>' +
        '<path d="M112 62 q20 6 30 2" stroke="#ffffff" stroke-width="4" fill="none" opacity=".42" stroke-linecap="round"/>' +
        '<circle cx="100" cy="100" r="64" fill="none" stroke="#8fd3ff" stroke-width="3.2" opacity=".22"/>';
    }
    if (key === 'mars') {
      features =
        '<ellipse cx="100" cy="46" rx="19" ry="7" fill="#ffffff" opacity=".8"/>' +
        '<circle cx="76" cy="96" r="8" fill="#a34a28" opacity=".42"/>' +
        '<circle cx="121" cy="122" r="11" fill="#a34a28" opacity=".38"/>' +
        '<path d="M50 116 q26 14 54 6 t46 2" stroke="#b8522c" stroke-width="5" fill="none" opacity=".35" stroke-linecap="round"/>' +
        '<path d="M58 78 q24 -8 46 -2" stroke="#f0a385" stroke-width="4" fill="none" opacity=".28" stroke-linecap="round"/>';
    }
    if (key === 'jupiter') {
      /* Bands + the Great Red Spot.                  [L3-Signaling] the spot is
         drawn as one clear feature because the narration points at it. */
      features =
        '<path d="M40 74 q60 -12 120 0" stroke="#c08a4e" stroke-width="9" fill="none" opacity=".45"/>' +
        '<path d="M38 98 q62 12 124 0" stroke="#ffe3c0" stroke-width="11" fill="none" opacity=".5"/>' +
        '<path d="M40 124 q60 -12 120 0" stroke="#c08a4e" stroke-width="8" fill="none" opacity=".42"/>' +
        '<path d="M44 140 q56 -8 112 0" stroke="#e0b98a" stroke-width="6" fill="none" opacity=".3"/>' +
        /* 大红斑：由外到内四层 + 两道旋涡线，放大后像风暴而不是"一坨红" */
        '<ellipse cx="122" cy="117" rx="21" ry="11" fill="#c94f33" opacity=".45"/>' +
        '<ellipse cx="122" cy="117" rx="17" ry="8.6" fill="#d9603f"/>' +
        '<ellipse cx="122" cy="116" rx="11" ry="5.2" fill="#e8825d" opacity=".92"/>' +
        '<ellipse cx="119" cy="115" rx="5.6" ry="2.6" fill="#f4a883" opacity=".8"/>' +
        '<path d="M104 122 q16 7 34 -2" stroke="#a83f26" stroke-width="1.6" fill="none" opacity=".4"/>' +
        '<path d="M108 111 q14 -4 26 1" stroke="#ffd0b4" stroke-width="1.2" fill="none" opacity=".35"/>';
    }
    if (key === 'saturn') {
      features =
        '<path d="M42 86 q60 -10 120 0" stroke="#cbb27c" stroke-width="7" fill="none" opacity=".35"/>' +
        '<path d="M42 114 q60 10 120 0" stroke="#cbb27c" stroke-width="7" fill="none" opacity=".35"/>' +
        '<path d="M46 72 q58 -8 116 0" stroke="#fff6de" stroke-width="4" fill="none" opacity=".3"/>';
    }
    if (key === 'uranus') {
      features =
        '<path d="M46 92 q56 -8 110 0" stroke="#5fc2cc" stroke-width="6" fill="none" opacity=".3"/>' +
        '<path d="M46 116 q56 8 110 0" stroke="#5fc2cc" stroke-width="6" fill="none" opacity=".26"/>';
    }
    if (key === 'neptune') {
      features =
        '<path d="M42 90 q58 -10 116 0" stroke="#3f5fc4" stroke-width="8" fill="none" opacity=".3"/>' +
        '<path d="M42 118 q58 10 116 0" stroke="#3f5fc4" stroke-width="8" fill="none" opacity=".26"/>' +
        '<ellipse cx="78" cy="106" rx="15" ry="8" fill="#26408f" opacity=".45"/>' +
        '<path d="M96 142 q22 6 40 -2" stroke="#d7e2ff" stroke-width="3.4" fill="none" opacity=".35" stroke-linecap="round"/>';
    }

    let ringBack = '', ringFront = '';
    if (key === 'saturn') {
      ringBack =
        '<g transform="rotate(-14 100 100)">' +
          '<ellipse cx="100" cy="100" rx="95" ry="26" fill="none" stroke="' + c[1] + '" stroke-width="11" opacity=".55"/>' +
          '<ellipse cx="100" cy="100" rx="79" ry="20" fill="none" stroke="' + c[0] + '" stroke-width="4" opacity=".5"/>' +
        '</g>';
      ringFront =
        '<g class="ring-spin" transform="rotate(-14 100 100)">' +
          '<path d="M 5 100 A 95 26 0 0 0 195 100" fill="none" stroke="' + c[1] + '" stroke-width="11"/>' +
          '<path d="M 21 100 A 79 20 0 0 0 179 100" fill="none" stroke="' + c[0] + '" stroke-width="4" opacity=".8"/>' +
          '<path d="M 12 100 A 88 23 0 0 0 188 100" fill="none" stroke="#fffdf5" stroke-width="1" opacity=".5"/>' +
        '</g>';
    }
    if (key === 'uranus') {
      ringBack =
        '<g transform="rotate(78 100 100)">' +
          '<ellipse cx="100" cy="100" rx="86" ry="16" fill="none" stroke="' + c[1] + '" stroke-width="2.4" opacity=".4"/>' +
        '</g>';
    }

    inner = ringBack +
      '<circle cx="' + cx + '" cy="' + cy + '" r="' + bodyR + '" fill="url(#' + uid + '-body)"/>' +
      '<g clip-path="url(#' + uid + '-clip)">' + features + '</g>' +
      '<g clip-path="url(#' + uid + '-clip)">' +
        '<circle cx="' + cx + '" cy="' + cy + '" r="' + bodyR + '" fill="url(#' + uid + '-shade)"/>' +
        '<ellipse cx="76" cy="72" rx="24" ry="16" fill="url(#' + uid + '-spec)" opacity=".55"/>' +
      '</g>' +
      '<circle cx="' + cx + '" cy="' + cy + '" r="' + (bodyR - .5) + '" fill="none" stroke="#ffffff" stroke-width="1" opacity=".16"/>' +
      ringFront +
      (o.face ? faceMarkup(cx, cy - 5, 1.55) : '');
  }

  /* Illustrations are decorative to assistive tech: every planet sits next to
     visible text (name, keyword, caption), so labelling the SVG too would make
     screen readers say everything twice.                    [L3-Redundancy] */
  return '<svg viewBox="0 0 ' + S + ' ' + S + '" width="' + size + '" height="' + size + '" aria-hidden="true" focusable="false">' +
    '<defs>' +
      '<radialGradient id="' + uid + '-body" cx="34%" cy="28%" r="82%">' +
        '<stop offset="0%" stop-color="' + c[0] + '"/>' +
        '<stop offset="56%" stop-color="' + c[1] + '"/>' +
        '<stop offset="100%" stop-color="' + c[2] + '"/>' +
      '</radialGradient>' +
      '<radialGradient id="' + uid + '-shade" cx="74%" cy="78%" r="78%">' +
        '<stop offset="42%" stop-color="#040814" stop-opacity="0"/>' +
        '<stop offset="74%" stop-color="#040814" stop-opacity=".35"/>' +
        '<stop offset="100%" stop-color="#02050f" stop-opacity=".88"/>' +
      '</radialGradient>' +
      '<radialGradient id="' + uid + '-spec" cx="50%" cy="50%" r="50%">' +
        '<stop offset="0%" stop-color="#ffffff" stop-opacity=".55"/>' +
        '<stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>' +
      '</radialGradient>' +
      '<radialGradient id="' + uid + '-glow" cx="50%" cy="50%" r="50%">' +
        '<stop offset="45%" stop-color="' + c[1] + '" stop-opacity=".5"/>' +
        '<stop offset="100%" stop-color="' + c[1] + '" stop-opacity="0"/>' +
      '</radialGradient>' +
      '<clipPath id="' + uid + '-clip"><circle cx="' + cx + '" cy="' + cy + '" r="60"/></clipPath>' +
    '</defs>' +
    inner +
  '</svg>';
}

/* ---------- 5. Guide character ---------- */
/* 向导地小球 / Earthie 的形象：桌面 6329 文件夹里的普通形态与四种情绪（assets/terra/）。
   五个形态内嵌成 data URI，所以没有任何外部请求；单文件版构建照旧可用。
   guideSVG(mood) 里的 mood 取 normal / happy / curious / celebrate / confused。 */
var TERRA_ART = {
  normal: "data:image/png;base64,",
  happy: "data:image/png;base64,",
  curious: "data:image/png;base64,",
  celebrate: "data:image/png;base64,",
  confused: "data:image/png;base64,"
};
function guideSVG(mood) {
  var src = TERRA_ART[mood] || TERRA_ART.normal;
  return '<svg viewBox="0 0 120 120" role="img" aria-label="Earthie the guide">' +
    '<image href="' + src + '" x="0" y="0" width="120" height="120" preserveAspectRatio="xMidYMid meet"/>' +
  '</svg>';
}

/* ---------- 6. Pre-training term icons ---------- */
function termIconSVG(key) {
  /* Each icon carries its own gradient defs (unique ids) so the sphere shading
     never depends on another icon being present. */
  const wrap = function (id, body) {
    return '<svg viewBox="0 0 100 100" fill="none" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<defs>' +
        '<radialGradient id="ti-' + id + '-body" cx="34%" cy="30%" r="80%">' +
          '<stop offset="0%" stop-color="' + (id === 'star' ? '#fff3cf' : '#bfe9ff') + '"/>' +
          '<stop offset="58%" stop-color="' + (id === 'star' ? '#ffc24b' : '#58b6ee') + '"/>' +
          '<stop offset="100%" stop-color="' + (id === 'star' ? '#e8890c' : '#1b5fa8') + '"/>' +
        '</radialGradient>' +
        '<radialGradient id="ti-' + id + '-shade" cx="72%" cy="76%" r="76%">' +
          '<stop offset="46%" stop-color="#040814" stop-opacity="0"/>' +
          '<stop offset="100%" stop-color="#040814" stop-opacity=".55"/>' +
        '</radialGradient>' +
        '<clipPath id="ti-' + id + '-clip"><circle cx="50" cy="50" r="' + (id === 'star' ? 24 : 27) + '"/></clipPath>' +
      '</defs>' + body + '</svg>';
  };
  if (key === 'star') {
    /* 直接复用模块 2 / 首页动画里那颗太阳（planetSVG('sun')）：
       同一个太阳在这个网站的任何页面都长得一样，不再出现"两个版本的太阳"。 */
    return planetSVG('sun', 104);
  }
  if (key === 'planet') {
    return wrap('planet',
      '<circle cx="50" cy="50" r="27" fill="url(#ti-planet-body)"/>' +
      '<g clip-path="url(#ti-planet-clip)">' +
        '<path d="M38 42 q11 -7 20 -1 q7 5 0 10 q-10 7 -20 -1 q-4 -4 0 -8z" fill="#4fae7a" opacity=".9"/>' +
        '<path d="M56 62 q9 -5 15 4 q3 7 -6 8 q-9 2 -9 -12z" fill="#4fae7a" opacity=".8"/>' +
        '<circle cx="50" cy="50" r="27" fill="url(#ti-planet-shade)"/>' +
        '<ellipse cx="42" cy="40" rx="8" ry="5.6" fill="#ffffff" opacity=".28"/>' +
      '</g>'
    );
  }
  if (key === 'orbit') {
    return wrap('orbit',
      /* 小太阳用与恒星卡、模块 2 相同的渐变（原来是一个扁平金圆，和其他地方的太阳不是一套） */
      '<circle cx="50" cy="50" r="12" fill="url(#ti-orbit-body)"/>' +
      '<circle cx="50" cy="50" r="12" fill="none" stroke="#fff8dc" stroke-width=".8" opacity=".5"/>' +
      '<ellipse cx="50" cy="50" rx="39" ry="25" stroke="#7fd8ff" stroke-width="1.6" opacity=".55"/>' +
      '<circle cx="88" cy="50" r="8" fill="#58b6ee"/>' +
      '<circle cx="88" cy="50" r="8" fill="none" stroke="#bfe9ff" stroke-width=".8" opacity=".6"/>' +
      '<path d="M50 25 l7 -6 l7 6" stroke="#ffc24b" stroke-width="2.2" opacity=".9"/>'
    );
  }
  return wrap('moon',
    '<circle cx="45" cy="54" r="25" fill="#58b6ee"/>' +
    '<path d="M34 48 q10 -6 19 -1" stroke="#4fae7a" stroke-width="5" fill="none" opacity=".8"/>' +
    '<circle cx="83" cy="30" r="9" fill="#cfd6e4"/>' +
    '<circle cx="79" cy="27" r="2.6" fill="#9aa3b4"/>' +
    '<ellipse cx="38" cy="44" rx="7" ry="4.6" fill="#ffffff" opacity=".25"/>'
  );
}

/* ---------- 7. Solar System: correct orbital model + renderer ----------
   Real values (NASA fact sheets) drive everything the learner can check:
     a   semi-major axis, AU · e orbital eccentricity · diaKm diameter
     yearDays orbital period · tiltDeg axial tilt · dayHours rotation

   Two honest compromises, both stated in the caption and the design notes:
   1. SIZES are compressed. True scale is impossible on screen (the Sun is 109×
      Earth and Neptune is 30 AU out), so bodies keep their correct ORDER and a
      damped ratio (exponent 0.24). Every real diameter is shown in the info card.
   2. SPEED keeps the correct direction and the correct order of speeds
      (inner = faster, period ∝ a^0.6 instead of a^1.5) so a class can see the
      pattern without waiting 165 years for Neptune.
   Everything else is as real as a 2-D diagram can be: prograde (anticlockwise
   seen from above the Sun's north pole) motion for all eight planets, elliptical
   orbits with the Sun at one focus, Saturn's rings, Uranus's near-vertical tilt. */
const SOLAR_DATA = [
  { key: 'mercury', zh: '水星', en: 'Mercury', a: 0.3871, e: 0.2056, diaKm: 4879, yearDays: 88.0, dayHours: 1407.6, tiltDeg: 0.03 },
  { key: 'venus', zh: '金星', en: 'Venus', a: 0.7233, e: 0.0068, diaKm: 12104, yearDays: 224.7, dayHours: 5832.5, tiltDeg: 177.4 },
  { key: 'earth', zh: '地球', en: 'Earth', a: 1.0000, e: 0.0167, diaKm: 12756, yearDays: 365.25, dayHours: 23.9, tiltDeg: 23.44 },
  { key: 'mars', zh: '火星', en: 'Mars', a: 1.5237, e: 0.0934, diaKm: 6792, yearDays: 687.0, dayHours: 24.6, tiltDeg: 25.19 },
  { key: 'jupiter', zh: '木星', en: 'Jupiter', a: 5.2026, e: 0.0489, diaKm: 142984, yearDays: 4332.6, dayHours: 9.9, tiltDeg: 3.13 },
  { key: 'saturn', zh: '土星', en: 'Saturn', a: 9.5549, e: 0.0565, diaKm: 120536, yearDays: 10759, dayHours: 10.7, tiltDeg: 26.73 },
  { key: 'uranus', zh: '天王星', en: 'Uranus', a: 19.2184, e: 0.0457, diaKm: 51118, yearDays: 30687, dayHours: 17.2, tiltDeg: 97.77 },
  { key: 'neptune', zh: '海王星', en: 'Neptune', a: 30.1104, e: 0.0113, diaKm: 49528, yearDays: 60190, dayHours: 16.1, tiltDeg: 28.32 }
];
const SOLAR_SUN = { diaKm: 1392700, surfaceC: 5500, rotationDays: 25.4 };

/* display model ------------------------------------------------------------ */
const SOLAR_VIEW = { w: 560, h: 300, cx: 280, cy: 150, tilt: 0.52 };
const SOLAR_ORBIT_BASE = 8;                                  /* 让水星离太阳有呼吸空间 */
/* 光有对数压缩还不够：内圈（水星—火星）会被挤到一起，水星甚至贴到太阳表面上。
   所以再加两条硬约束：
     · 水星轨道离"太阳表面"至少留 14 个显示单位；
     · 相邻两条轨道之间至少 18 个显示单位。
   外圈本来就很宽（间距 35–44），所以这两条只影响内圈，不会把图撑爆。 */
const SOLAR_ORBIT_MIN_GAP = 18;
const SOLAR_MERCURY_CLEARANCE = 14;
const SOLAR_ORBIT_R = (function () {
  const out = {};
  let prev = 0;
  /* 这里不能调用 solarBodyR()——它在本文件更下面才初始化，会踩到暂时性死区。
     太阳的显示半径用同一个公式就地算一遍（数值与 solarBodyR 一致）。 */
  const sunR = Math.round(6.0 * Math.pow(SOLAR_SUN.diaKm / 12756, 0.24) * 100) / 100;
  SOLAR_DATA.forEach(function (p, i) {
    let r = SOLAR_ORBIT_BASE + 68 * Math.log(1 + p.a / 1.1);
    r = (i === 0) ? Math.max(r, sunR + SOLAR_MERCURY_CLEARANCE) : Math.max(r, prev + SOLAR_ORBIT_MIN_GAP);
    out[p.key] = Math.round(r * 100) / 100;
    prev = r;
  });
  return out;
})();
function solarOrbitR(a) {
  const p = SOLAR_DATA.find(function (d) { return Math.abs(d.a - a) < 0.001; });
  return (p && SOLAR_ORBIT_R[p.key]) || (SOLAR_ORBIT_BASE + 68 * Math.log(1 + a / 1.1));
}
/* 压缩比例（指数 0.24）：让八颗行星能同时挤在一屏里。
   太阳不再写死常数，改用同一个公式算，所以"太阳比木星大"这件事仍然成立。 */
const solarBodyR = (diaKm) => Math.round(6.0 * Math.pow(diaKm / 12756, 0.24) * 100) / 100;
const solarPeriodSec = a => Math.round(15 * Math.pow(a, 0.6) * 10) / 10;

/* geometry: Sun sits at one focus, so the ellipse centre is offset by c = a·e */
function solarPoint(p, t) {
  const a = solarOrbitR(p.a), e = p.e;
  const c = a * e;
  const rx = a, ry = a * Math.sqrt(1 - e * e);
  const x = SOLAR_VIEW.cx + c + rx * Math.cos(t);
  const y = SOLAR_VIEW.cy - ry * SOLAR_VIEW.tilt * Math.sin(t);
  return { x: x, y: y, a: a, rx: rx, ry: ry, c: c };
}
/* a planet's displayed radius; the Sun is drawn from its own scale */
const solarRadius = key => {
  const p = SOLAR_DATA.find(d => d.key === key);
  return p ? solarBodyR(p.diaKm) : solarBodyR(SOLAR_SUN.diaKm);
};

/* ---------- 拖拽游戏用的显示尺寸 ----------
   与上面的太阳系动画共用同一套压缩模型（solarBodyR），所以"首页动画里木星比地球大"
   和"拖拽游戏里木星的圆圈更大"是一致的。真实直径差异被压缩过（木星 11×地球、29×水星），
   所以游戏里另外用文字把真实倍数标出来，避免把压缩当成真实比例。
   GAME_UNIT 只是把显示单位换算成像素，不改变任何比例关系。 */
const GAME_UNIT = 4.8;
function solarDiaKm(key) {
  if (key === 'sun') return SOLAR_SUN.diaKm;
  const p = SOLAR_DATA.find(d => d.key === key);
  return p ? p.diaKm : 12756;
}
function solarGameDia(key) {
  return Math.round(solarBodyR(solarDiaKm(key)) * 2 * GAME_UNIT);
}
/* ---------- 复习页那一排天体的显示直径 ----------
   和首页动画、拖拽游戏共用同一套压缩模型（solarBodyR），所以"复习页里木星最大、
   水星最小"与前面几页是同一套关系，不会互相矛盾。
   SUMMARY_UNIT 只是把模型换算成像素：木星 77px、水星 34px（约 2.3 倍，肉眼分得出）。
   太阳真比例是地球的 109 倍，按模型算会到 133px，塞进这一排会把邻居挤没，
   所以单独给 120px —— 仍然是这一排里最大的一颗（可见球 96px > 木星 77px）。 */
const SUMMARY_UNIT = 3.6;
function summaryArtDia(key) {
  if (key === 'sun') return 120;
  return Math.round(solarBodyR(solarDiaKm(key)) * 2 * SUMMARY_UNIT);
}
/* planetSVG 的画布是 200×200，球体只占其中 r=60（可见直径 120），
   所以要"可见球体正好填满直径 D 的圆圈"，画布必须放大 200/120 倍。
   不这样换算的话，放进去的行星看起来只有圆圈的 60% 大。 */
const PLANET_SVG_BOX = 200 / 120;
function planetArtBox(diaVisible) {
  return Math.round(diaVisible * PLANET_SVG_BOX);
}

/* ---------- 分段学习里的插图：按真实直径等比（不做压缩） ----------
   一次只并排显示同一组行星，所以可以老老实实按真实比例画：
   参考行星的可见直径 = refVisiblePx，其余天体按 diaKm 等比换算。
   例：solarArtPair('earth', 96) → 地球 96px、金星 91px、水星 37px、火星 51px。
   太阳单独给尺寸（真比例下它是地球的 109 倍，放不进任何一栏）。 */
function solarArtPair(refKey, refVisiblePx) {
  const refDia = solarDiaKm(refKey);
  const out = { sun: planetArtBox(Math.round(refVisiblePx * SOLAR_SUN.diaKm / refDia)) };
  SOLAR_DATA.forEach(function (p) {
    out[p.key] = planetArtBox(Math.round(refVisiblePx * p.diaKm / refDia));
  });
  return out;
}

function solarBodyArt(key, r, uid) {
  const c = PALETTE[key] || PALETTE.mercury;
  let ring = '';
  if (key === 'saturn') {
    ring = '<ellipse cx="0" cy="0" rx="' + (r * 1.95) + '" ry="' + (r * 0.62) + '" fill="none" stroke="' + c[1] + '" stroke-width="' + (r * 0.34) + '" opacity=".55" transform="rotate(-14)"/>' +
           '<ellipse cx="0" cy="0" rx="' + (r * 1.95) + '" ry="' + (r * 0.62) + '" fill="none" stroke="' + c[0] + '" stroke-width="' + (r * 0.12) + '" opacity=".8" transform="rotate(-14)"/>';
  }
  if (key === 'uranus') {
    ring = '<ellipse cx="0" cy="0" rx="' + (r * 1.9) + '" ry="' + (r * 0.9) + '" fill="none" stroke="' + c[1] + '" stroke-width="' + (r * 0.1) + '" opacity=".35" transform="rotate(76)"/>';
  }
  let bands = '';
  if (key === 'jupiter' || key === 'saturn') {
    bands = '<path d="M ' + (-r) + ' ' + (-r * 0.25) + ' q ' + r + ' ' + (-r * 0.35) + ' ' + (r * 2) + ' 0" stroke="' + c[0] + '" stroke-width="' + (r * 0.2) + '" fill="none" opacity=".45"/>' +
            '<path d="M ' + (-r) + ' ' + (r * 0.35) + ' q ' + r + ' ' + (r * 0.35) + ' ' + (r * 2) + ' 0" stroke="' + c[2] + '" stroke-width="' + (r * 0.16) + '" fill="none" opacity=".35"/>';
  }
  if (key === 'earth') {
    bands = '<path d="M ' + (-r * 0.7) + ' ' + (-r * 0.35) + ' q ' + r * 0.5 + ' ' + (-r * 0.5) + ' ' + (r * 0.9) + ' ' + (-r * 0.1) + ' q ' + r * 0.2 + ' ' + r * 0.35 + ' ' + (-r * 0.5) + ' ' + r * 0.3 + ' q ' + (-r * 0.6) + ' ' + (-r * 0.1) + ' ' + (-r * 0.4) + ' ' + (-r * 0.55) + 'z" fill="#63c98a" opacity=".85"/>';
  }
  if (key === 'mars') {
    bands = '<ellipse cx="0" cy="' + (-r * 0.72) + '" rx="' + (r * 0.42) + '" ry="' + (r * 0.16) + '" fill="#ffffff" opacity=".55"/>';
  }
  if (key === 'mercury') {
    bands = '<circle cx="' + (-r * 0.35) + '" cy="' + (r * 0.2) + '" r="' + (r * 0.22) + '" fill="#7f8695" opacity=".5"/>';
  }
  const shade = r >= 3 ? '<circle cx="0" cy="0" r="' + r + '" fill="url(#' + uid + '-shade)"/>' : '';
  const sheen = r >= 3 ? '<ellipse cx="' + (-r * 0.34) + '" cy="' + (-r * 0.38) + '" rx="' + (r * 0.5) + '" ry="' + (r * 0.34) + '" fill="url(#' + uid + '-sheen)" opacity=".5"/>' : '';
  return '<g class="solar-art">' +
      '<circle cx="0" cy="0" r="' + (r * 2.6) + '" fill="url(#' + uid + '-glow)" opacity=".55"/>' +
      ring +
      '<circle cx="0" cy="0" r="' + r + '" fill="url(#' + uid + '-body)"/>' +
      bands + shade + sheen +
      '<circle cx="0" cy="0" r="' + r + '" fill="none" stroke="#ffffff" stroke-opacity=".22" stroke-width="' + (Math.max(0.5, r * 0.055)).toFixed(2) + '"/>' +
    '</g>';
}

function solarDefs() {
  let defs = '';
  SOLAR_DATA.forEach(function (p) {
    const c = PALETTE[p.key];
    defs += '<radialGradient id="ss-' + p.key + '-body" cx="34%" cy="30%" r="82%">' +
        '<stop offset="0%" stop-color="' + c[0] + '"/><stop offset="56%" stop-color="' + c[1] + '"/><stop offset="100%" stop-color="' + c[2] + '"/></radialGradient>' +
      '<radialGradient id="ss-' + p.key + '-shade" cx="74%" cy="78%" r="78%">' +
        '<stop offset="40%" stop-color="#040814" stop-opacity="0"/><stop offset="78%" stop-color="#040814" stop-opacity=".4"/><stop offset="100%" stop-color="#02050f" stop-opacity=".9"/></radialGradient>' +
      '<radialGradient id="ss-' + p.key + '-sheen" cx="50%" cy="50%" r="50%">' +
        '<stop offset="0%" stop-color="#ffffff" stop-opacity=".5"/><stop offset="100%" stop-color="#ffffff" stop-opacity="0"/></radialGradient>' +
      '<radialGradient id="ss-' + p.key + '-glow" cx="50%" cy="50%" r="50%">' +
        '<stop offset="0%" stop-color="' + c[1] + '" stop-opacity=".3"/><stop offset="100%" stop-color="' + c[1] + '" stop-opacity="0"/></radialGradient>';
  });
  return '<defs>' + defs +
    '<radialGradient id="ss-sun-core" cx="38%" cy="34%" r="70%">' +
      '<stop offset="0%" stop-color="#fff8dd"/><stop offset="55%" stop-color="#ffc24b"/><stop offset="100%" stop-color="#e8890c"/></radialGradient>' +
    '<radialGradient id="ss-sun-glow" cx="50%" cy="50%" r="50%">' +
      '<stop offset="0%" stop-color="#ffd166" stop-opacity=".55"/><stop offset="45%" stop-color="#ffa53c" stop-opacity=".22"/><stop offset="100%" stop-color="#ff8c1a" stop-opacity="0"/></radialGradient>' +
  '</defs>';
}

/* The renderer. mode: 'hero' (clean, no labels) | 'diagram' (orbit labels +
   direction arrow, used in the lesson module). */
function solarSystemSVG(mode) {
  const diagram = mode === 'diagram';
  const V = SOLAR_VIEW;
  const rmix = t('太阳系：八颗行星沿椭圆轨道绕太阳公转（从太阳北极方向看，全部逆时针）',
                 'The Solar System: eight planets orbiting the Sun on elliptical paths, all anticlockwise seen from above the Sun’s north pole');
  let orbits = '';
  let bodies = '';

  SOLAR_DATA.forEach(function (p, i) {
    const a = solarOrbitR(p.a), c = a * p.e, ry = a * Math.sqrt(1 - p.e * p.e) * V.tilt;
    orbits += '<ellipse class="solar-orbit" data-orbit="' + p.key + '" cx="' + (V.cx + c) + '" cy="' + V.cy + '" rx="' + a + '" ry="' + ry + '" fill="none" stroke="#ffffff" stroke-opacity="' + (diagram ? 0.16 : 0.1) + '" stroke-width="1"/>';
    const r = solarBodyR(p.diaKm);
    const start = solarPoint(p, 0.9 + i * 0.93);   /* 各行星初始角度错开，避免连成一线 */
    bodies +=
      '<g class="solar-body" data-planet="' + p.key + '" data-r="' + r + '" transform="translate(' + start.x.toFixed(2) + ' ' + start.y.toFixed(2) + ')" tabindex="0" role="button" aria-label="' + t(p.zh, p.en) + '">' +
        '<polyline class="solar-trail" points="" fill="none" stroke="' + PALETTE[p.key][1] + '" stroke-opacity=".3" stroke-width="' + Math.max(1, r * 0.28) + '" stroke-linecap="round"/>' +
        solarBodyArt(p.key, r, 'ss-' + p.key) +
        /* label side follows the planet's starting position so text never runs
           outside the frame (outer planets start on the right more often) */
        (diagram ? (function () {
          const right = start.x >= V.cx;
          return '<text class="solar-label" x="' + (right ? -(r + 5) : (r + 5)) + '" y="' + (r + 4) + '" font-size="9" text-anchor="' + (right ? 'end' : 'start') + '" fill="#aab6da">' + t(p.zh, p.en) + '</text>';
        })() : '') +
        '<circle class="solar-hit" cx="0" cy="0" r="' + Math.max(r + 9, 15) + '" fill="transparent"/>' +
      '</g>';
  });

  const arrow = !diagram ? '' :
    '<g class="solar-arrow" opacity=".9">' +
      '<path d="M ' + (V.cx + 30) + ' ' + (V.cy - solarOrbitR(30.1104) * V.tilt) + ' A 30 30 0 0 1 ' + (V.cx + 150) + ' ' + (V.cy - 205) + '" fill="none" stroke="#ffc24b" stroke-opacity=".45" stroke-width="1.2"/>' +
      '<path d="M 0 0 l 7 4 l -7 4 z" fill="#ffc24b" transform="translate(' + (V.cx + 152) + ' ' + (V.cy - 206) + ') rotate(28)"/>' +
      '<text x="' + (V.cx + 66) + '" y="' + (V.cy - 176) + '" font-size="9" letter-spacing="1.4" fill="#ffc24b">' +
        t('公转方向', 'ORBIT DIRECTION').toUpperCase() + '</text>' +
    '</g>';

  return '<svg class="solar-svg" viewBox="0 0 ' + V.w + ' ' + V.h + '" role="img" data-aria-zh="' +
    '太阳系：八颗行星沿椭圆轨道绕太阳公转（从太阳北极方向看，全部逆时针）" data-aria-en="' +
    'The Solar System: eight planets orbiting the Sun on elliptical paths, all anticlockwise seen from above the Sun’s north pole" aria-label="' + rmix + '">' +
    solarDefs() +
    '<g class="solar-orbits">' + orbits + '</g>' +
    '<g class="solar-sun">' +
      '<circle cx="' + V.cx + '" cy="' + V.cy + '" r="' + (solarBodyR(SOLAR_SUN.diaKm) * 5.4) + '" fill="url(#ss-sun-glow)"/>' +
      '<circle cx="' + V.cx + '" cy="' + V.cy + '" r="' + (solarBodyR(SOLAR_SUN.diaKm) * 2.1) + '" fill="#ffb347" opacity=".18"/>' +
      '<circle cx="' + V.cx + '" cy="' + V.cy + '" r="' + solarBodyR(SOLAR_SUN.diaKm) + '" fill="url(#ss-sun-core)"/>' +
      '<circle cx="' + V.cx + '" cy="' + V.cy + '" r="' + solarBodyR(SOLAR_SUN.diaKm) + '" fill="none" stroke="#fff8dd" stroke-opacity=".55" stroke-width=".8"/>' +
      '<text class="solar-sun-label" x="' + V.cx + '" y="' + (V.cy + solarBodyR(SOLAR_SUN.diaKm) + 12) + '" font-size="9" letter-spacing="1.2" text-anchor="middle" fill="#ffdf9d">' +
        t('太阳', 'SUN').toUpperCase() + '</text>' +
    '</g>' +
    bodies + arrow +
  '</svg>';
}

/* back-compat wrapper: the lesson module asks for the diagram, the hero for the
   clean animated version (script.js drives the motion of both). */
function orbitMapSVG(compact) { return solarSystemSVG(compact ? 'hero' : 'diagram'); }

/* ---------- 8. Solar System lineup (learn page) ----------
   参照参考图 "for reference 2"（1598×534 黑底横排）：太阳在最左、大片暖色辉光，
   八颗行星从左到右排开、各自带柔光、位置略微高低错落。
   尺寸沿用同一套压缩模型（solarBodyR），所以这里的"木星约等于地球的 2.2 倍"
   与首页动画、拖拽游戏完全一致（参考图里也正好是这个比例）。
   每颗天体都是 .solar-body，因此点击后复用站内已有的行星资料卡。 */
function solarLineupSVG() {
  const W = 1360, H = 260, CY = 122, U = 5.5;     /* U = 每个显示单位多少 px */
  const order = [{ key: 'sun', zh: '太阳', en: 'Sun', sun: true }]
    .concat(SOLAR_DATA.map(function (p) { return { key: p.key, zh: p.zh, en: p.en }; }));
  /* 参考图：所有天体在同一条水平线上（不做高低错落），整张图是静止的 */
  const radii = order.map(function (b) {
    return Math.round(solarBodyR(b.sun ? SOLAR_SUN.diaKm : solarDiaKm(b.key)) * U * 10) / 10;
  });
  const total = radii.reduce(function (s, r) { return s + r * 2; }, 0);
  const gap = (W - 80 - total) / (order.length - 1);

  let x = 40, out = '';
  order.forEach(function (b, n) {
    const r = radii[n];
    x += r;
    const box = planetArtBox(r * 2);          /* planetSVG 的球体只占画布 60%，画布要放大 */
    const label = t(b.zh, b.en);
    out +=
      '<g class="solar-body" data-planet="' + b.key + '" data-r="' + r + '" transform="translate(' + x.toFixed(1) + ' ' + CY + ')" tabindex="0" role="button" aria-label="' + label + '">' +
        /* 太阳先铺一层暖色辉光，再用与拖拽游戏相同的太阳图形盖在上面 */
        (b.sun ? '<circle cx="0" cy="0" r="' + (r * 3.2) + '" fill="url(#ss-sun-glow)"/>' : '') +
        /* planetSVG 的坐标以 (100,100) 为中心，这里把它平移回 group 原点 */
        /* 内联样式钉死尺寸：否则外层 .orbit-map svg{width:100%} 之类的规则会把这个嵌套 SVG 拉大/压小 */
        '<g transform="translate(' + (-box / 2) + ' ' + (-box / 2) + ')">' + planetSVG(b.key, box).replace('<svg ', '<svg style="width:' + box + 'px;height:' + box + 'px" ') + '</g>' +
        '<circle class="solar-hit" cx="0" cy="0" r="' + Math.max(r + 12, 20) + '" fill="transparent"/>' +
        '<text class="solar-label lineup-label" x="0" y="' + (r + 26) + '" text-anchor="middle" font-size="14">' + label + '</text>' +
      '</g>';
    x += r + gap;
  });

  return '<svg class="solar-svg lineup-svg" viewBox="0 0 ' + W + ' ' + H + '" role="img" data-aria-zh="太阳系横排示意图：左边是太阳，往右依次是八颗行星" data-aria-en="Solar System in a row: the Sun on the left, then the eight planets" aria-label="' +
      t('太阳系横排示意图：左边是太阳，往右依次是八颗行星，点任意一颗看它的资料卡', 'Solar System in a row: the Sun on the left, then the eight planets — tap any one for its card') + '">' +
    solarDefs() +
    '<defs><linearGradient id="lineup-band" x1="0" y1="0" x2="1" y2="0">' +
      '<stop offset="0%" stop-color="#ffc24b" stop-opacity=".16"/>' +
      '<stop offset="45%" stop-color="#ff9d3c" stop-opacity=".07"/>' +
      '<stop offset="100%" stop-color="#7fd8ff" stop-opacity=".05"/>' +
    '</linearGradient></defs>' +
    '<rect x="0" y="' + (CY - 74) + '" width="' + W + '" height="150" rx="75" fill="url(#lineup-band)"/>' +
    out +
  '</svg>';
}
